// Gleiche Logik wie im Cockpit (lib/derive.ts, matchKriterien) – Standort zuerst,
// Entscheidung im Demo-Check 20.08. Datenbasis ist seit dem Sales-Update 28.09. die
// TÄGLICH AKTUALISIERTE LIVELISTE aus OneDrive, nicht ein gespeichertes Ankaufsprofil:
// der Vertrieb pflegt dort u. a. die letzten Ankäufe je Investor.
// Erwartet: { objekt: { region, assetklasse, kaufpreisMio },
//             liveliste: { stand, investoren: [{ id, regionen, assetklassen, ticketMinMio, ticketMaxMio,
//                                                letzteAnkaeufe?: [{ assetklasse, region, jahr }] }] } }
const OBERMENGEN = ['Rhein-Main', 'Hessen', 'Deutschland', 'Deutschland Top-7', 'DACH'];
const { objekt, liveliste } = $input.first().json;
const investoren = liveliste?.investoren ?? [];
const stand = liveliste?.stand ?? null;
const teileDes = (wert) => String(wert ?? '').split(' / ').filter(Boolean);
const treffer = investoren.map((inv) => {
  const standort = (inv.regionen ?? []).some((r) => OBERMENGEN.includes(r) || r === objekt.region);
  const teile = teileDes(objekt.assetklasse);
  const assetklasse = (inv.assetklassen ?? []).length === 0 ? null
    : (inv.assetklassen).some((a) => teile.some((t) => a.includes(t) || t.includes(a)));
  // Fehlt eine Angabe in der Liveliste, gilt das Kriterium als unbekannt und nicht
  // als nicht erfuellt. Die echte Liste ist bei Assetklasse und Ticket nur teilweise
  // gepflegt; ein hartes Nein wuerde fast jeden Investor aussortieren.
  const ticket = (inv.ticketMinMio === null && inv.ticketMaxMio === null) ? null
    : ((inv.ticketMinMio ?? -Infinity) <= objekt.kaufpreisMio && objekt.kaufpreisMio <= (inv.ticketMaxMio ?? Infinity));
  // Zusatzsignal aus der Liveliste: hat der Investor zuletzt Vergleichbares gekauft?
  const letzte = inv.letzteAnkaeufe ?? [];
  const kaufteAehnlich = letzte.some((k) => teile.some((t) => String(k.assetklasse ?? '').includes(t)));
  const unbekannt = [assetklasse === null && 'Assetklasse', ticket === null && 'Ticketspanne'].filter(Boolean);
  const voll = standort && assetklasse !== false && ticket !== false && unbekannt.length === 0;
  return { json: { investorId: inv.id, standort, assetklasse, ticket, kaufteAehnlich, voll,
                   listeStand: stand, unbekannt, hinweis: voll ? null : (unbekannt.length ? 'unvollstaendig in der Liveliste: ' + unbekannt.join(', ') : 'manuell pruefen') } };
});
// Standort ist K.-o. nur fuer den AUTOMATISCHEN Vorschlag – Rest sortiert nach Trefferqualitaet.
return treffer.sort((a, b) =>
  Number(b.json.voll) - Number(a.json.voll) || Number(b.json.kaufteAehnlich) - Number(a.json.kaufteAehnlich));

// Excel-Zeilen der Liveliste in die Struktur bringen, die der Abgleich erwartet.
// Spaltenzuordnung steht in „Konfiguration Liveliste“ – beim Setup an die echte Liste anpassen.
const roh = $input.first().json;
const konf = $('Konfiguration Liveliste (Platzhalter)').first().json;
if (roh.error) throw new Error('Liveliste nicht lesbar – SharePoint-Zugriff (Sites.Selected) oder IDs prüfen: ' + JSON.stringify(roh.error));
const werte = roh.values ?? [];
if (werte.length < 2) throw new Error('Liveliste leer oder ohne Kopfzeile');
const kopf = werte[0].map(k => String(k ?? '').trim());
const spalten = JSON.parse(konf.spalten ?? '{}');
const idx = (name) => kopf.findIndex(k => k.toLowerCase() === String(name ?? '').toLowerCase());
const liste = (v) => String(v ?? '').split(/[;,/]/).map(s => s.trim()).filter(Boolean);
const zahl = (v) => { const z = parseFloat(String(v ?? '').replace(',', '.')); return Number.isFinite(z) ? z : null; };
const investoren = werte.slice(1).filter(z => z.some(c => String(c ?? '').trim() !== '')).map((z, i) => {
  const feld = (schl) => { const j = idx(spalten[schl]); return j >= 0 ? z[j] : undefined; };
  const ank = liste(feld('letzteAnkaeufe')).map(t => ({ assetklasse: t, region: '', jahr: null }));
  // Ticketspanne: entweder zwei Spalten, oder eine Spalte der Form "1000000-10000000".
  // Werte ab 100000 werden als Euro gelesen und in Millionen umgerechnet.
  let tMin = zahl(feld('ticketMinMio')), tMax = zahl(feld('ticketMaxMio'));
  const spanne = String(feld('sweetspot') ?? '').trim();
  if ((tMin === null || tMax === null) && spanne) {
    const teile = spanne.split(/\s*(?:-|bis|–)\s*/).map(zahl).filter(z => z !== null);
    if (teile.length >= 1) {
      const skal = (z) => (z >= 100000 ? z / 1000000 : z);
      tMin = skal(teile[0]);
      tMax = teile.length > 1 ? skal(teile[1]) : null;
    }
  }
  return { id: String(feld('id') ?? ('zeile-' + (i + 2))), regionen: liste(feld('regionen')), assetklassen: liste(feld('assetklassen')),
           ticketMinMio: tMin, ticketMaxMio: tMax, letzteAnkaeufe: ank,
           roh: Object.fromEntries(kopf.map((k, j) => [k, z[j]])) };
});
const objekt = konf.objekt ?? konf.body?.objekt ?? {};
return [{ json: { objekt, liveliste: { stand: new Date().toISOString(), quelle: 'OneDrive/Graph', investoren } } }];
